class AppError(Exception):
    pass


def go_quote(text):
    return json.dumps(str(text), ensure_ascii=False)


def os_error(err, operation='open', path=None):
    name = path if path is not None else err.filename
    reason = {1: 'operation not permitted', 2: 'no such file or directory',
              13: 'permission denied', 17: 'file exists', 20: 'not a directory',
