    'result-row': {'number-color': '#e67100', 'directory-color': '#3498db'},
    'header': {'text-color': '#000000', 'background-color': '#2479D0', 'hidden': False},
    'progress-modal': {'current-item-path-max-len': 0},
    'use-old-size-bar': False,
}
DEFAULTS = {
    'style': STYLE, 'sorting': {'by': '', 'order': ''},
    'log-file': '/dev/null', 'input-file': '', 'output-file': '', 'ignore-from-file': '',
    'ignore-dirs': ['/proc', '/dev', '/sys', '/run'], 'ignore-dir-patterns': [],
    'type': [], 'exclude-type': [], 'max-cores': os.cpu_count() or 1, 'top': 0, 'depth': 0,
