    'show-annexed-size': False, 'show-item-count': False, 'show-mtime': False,
    'no-color': False, 'mouse': False, 'non-interactive': False, 'no-progress': False,
    'no-unicode': False, 'no-cross': False, 'no-hidden': False, 'no-delete': False,
    'no-spawn-shell': False, 'follow-symlinks': False, 'profiling': False,
    'read-from-storage': False, 'db': '', 'summarize': False, 'use-si-prefix': False,
    'no-prefix': False, 'show-in-kib': False, 'reverse-sort': False, 'change-cwd': False,
    'delete-in-background': False, 'delete-in-parallel': False,
    'since': '', 'until': '', 'max-age': '', 'min-age': '',
    'archive-browsing': False, 'collapse-path': False,
}
# flag -> (configuration key, shorthand, value type)
FLAGS = {}
for key, short in [
    ('archive-browsing',''), ('collapse-path',''), ('follow-symlinks','L'), ('mouse',''),
    ('no-color','c'), ('no-cross','x'), ('no-delete',''), ('no-hidden','H'), ('no-prefix',''),
    ('no-progress','p'), ('no-spawn-shell',''), ('no-unicode','u'), ('non-interactive','n'),
    ('read-from-storage','r'), ('reverse-sort',''), ('show-annexed-size','A'),
    ('show-apparent-size','a'), ('show-disks','d'), ('show-in-kib','k'),
    ('show-item-count','C'), ('show-mtime','M'), ('show-relative-size','B'),
    ('summarize','s'), ('version','v'), ('write-config',''), ('help','h')]:
    FLAGS[key] = (key, short, bool)
for flag,key in [('sequential','sequential-scanning'), ('si','use-si-prefix'),
                 ('enable-profiling','profiling')]:
    FLAGS[flag]=(key,'',bool)
for key,short,kind in [('config-file','',str),('db','D',str), ('depth','',int),
        ('exclude-type','E',list), ('input-file','f',str), ('log-file','l',str),
        ('max-age','',str), ('min-age','',str), ('since','',str), ('until','',str),
        ('max-cores','m',int), ('output-file','o',str), ('top','t',int),
        ('type','T',list), ('ignore-dirs','i',list)]:
    FLAGS[key]=(key,short,kind)
FLAGS['ignore-dirs-pattern']=('ignore-dir-patterns','I',list)
FLAGS['ignore-from']=('ignore-from-file','X',str)
SHORT={v[1]:k for k,v in FLAGS.items() if v[1]}


def parse_bool(v):
    if v in ('1','t','T','TRUE','true','True'): return True
    if v in ('0','f','F','FALSE','false','False'): return False
    raise ValueError()


def parse_int(v):
    text=v
    sign=1
    if text.startswith(('+','-')):
        if text[0]=='-': sign=-1
        text=text[1:]
    if not text: raise ValueError('invalid syntax')
    base=10
    if text.lower().startswith(('0x','0o','0b')):
        base={'x':16,'o':8,'b':2}[text[1].lower()];text=text[2:]
        text=text.lstrip('_') if text.startswith('_') else text
    elif len(text)>1 and text.startswith('0'): base=8
    if not re.fullmatch({10:r'[0-9]+(?:_[0-9]+)*',8:r'[0-7]+(?:_[0-7]+)*',
                         2:r'[01]+(?:_[01]+)*',16:r'[0-9a-fA-F]+(?:_[0-9a-fA-F]+)*'}[base],text):
        raise ValueError('invalid syntax')
    x=sign*int(text.replace('_',''),base)
    if not -(2**63)<=x<2**63: raise ValueError('value out of range')
    return x


def parse_args(args):
    values={};pos=[];i=0
    def setflag(flag,value):
        key,short,kind=FLAGS[flag]
        try:
            if kind is bool: result=parse_bool(value)
            elif kind is int: result=parse_int(value)
            elif kind is list:
                result=next(csv.reader([value], strict=True)) if value else []
            else: result=value
        except (ValueError,csv.Error) as e:
            label=f'-{short}, --{flag}' if short else f'--{flag}'
            if kind is int:
                cause=f'strconv.ParseInt: parsing {go_quote(value)}: {str(e) or "invalid syntax"}'
            elif kind is bool:
                cause=f'strconv.ParseBool: parsing {go_quote(value)}: invalid syntax'
            else:
                cause='parse error on line 1, column 1: bare " in non-quoted-field'
            raise AppError(f'invalid argument {go_quote(value)} for {go_quote(label)} flag: {cause}')
        if kind is list and key in values: values[key].extend(result)
        else: values[key]=result
    while i<len(args):
        word=args[i]; i+=1
        if word=='--':pos.extend(args[i:]);break
        if word.startswith('--'):
            flag,eq,value=word[2:].partition('=')
            if flag not in FLAGS:raise AppError('unknown flag: --'+flag)
            if not eq:
                if FLAGS[flag][2] is bool: value='true'
                elif i<len(args): value=args[i];i+=1
                else: raise AppError('flag needs an argument: --'+flag)
            setflag(flag,value)
        elif word.startswith('-') and word!='-':
            rest=word[1:]
            while rest:
                short=rest[0];current=rest;rest=rest[1:]
                if short not in SHORT:
                    raise AppError(f"unknown shorthand flag: '{short}' in -{current}")
                flag=SHORT[short];kind=FLAGS[flag][2]
                if rest.startswith('='):
                    value=rest[1:];rest=''
                elif kind is bool:value='true'
                elif rest:value=rest;rest=''
                elif i<len(args):value=args[i];i+=1
                else:raise AppError(f"flag needs an argument: '{short}' in -{current}")
                setflag(flag,value)
        else:pos.append(word)
    if not values.get('help') and len(pos)>1:
        raise AppError(f'accepts at most 1 arg(s), received {len(pos)}')
    return values,pos


def split_yaml(s,separator=','):
    parts=[];start=0;depth=0;quote='';i=0
    while i<len(s):
        ch=s[i]
        if quote:
            if ch==quote and (i==0 or s[i-1]!='\\'): quote=''
        elif ch in '\"\'':quote=ch
        elif ch in '[{':depth+=1
        elif ch in ']}':depth-=1
        elif ch==separator and not depth:parts.append(s[start:i]);start=i+1
        i+=1
    if quote or depth:raise ValueError('unclosed value')
    parts.append(s[start:]);return parts


def scalar(text):
    text=text.strip()
    if not text:return None
    if text.startswith('"'):return json.loads(text)
    if text.startswith("'"):
        if not text.endswith("'"):raise ValueError()
        return text[1:-1].replace("''", "'")
    text=re.split(r'\s+#',text,1)[0].rstrip()
    if text.startswith('['):
        if not text.endswith(']'):raise ValueError()
        return [scalar(x) for x in split_yaml(text[1:-1])] if text[1:-1].strip() else []
    if text.startswith('{'):
        if not text.endswith('}'):raise ValueError()
        return dict((k.strip(),scalar(v)) for k,v in (p.split(':',1) for p in split_yaml(text[1:-1]))) if text[1:-1].strip() else {}
    if text.lower() in ['true','false']:return text.lower()=='true'
    if text.lower() in ['null','~']:return None
    if re.fullmatch(r'[-+]?\d+',text):return int(text)
    return text


def read_yaml(text):
    stripped=text.strip()
    if stripped.startswith('{'):return json.loads(stripped)
    lines=[]
    for line in text.splitlines():
        if not line.strip() or line.lstrip().startswith(('#','---','...')):continue
        indent=len(line)-len(line.lstrip(' ')); lines.append((indent,line.strip()))
    def parse_block(index,indent):
        islist=lines[index][1].startswith('- ')
        result=[] if islist else {}
        while index<len(lines) and lines[index][0]>=indent:
            level,body=lines[index]
            if level!=indent:raise ValueError('indentation')
            if islist:
                if not body.startswith('- '):break
                result.append(scalar(body[2:]));index+=1
            else:
                if ':' not in body:raise ValueError()
                key,value=body.split(':',1);key=key.strip().strip('"\'');index+=1
                if not value.strip() and index<len(lines) and lines[index][0]>indent:
                    val,index=parse_block(index,lines[index][0])
                else:val=scalar(value)
                result[key]=val
        return result,index
    if not lines:return {}
    return parse_block(0,lines[0][0])[0]


def merge_config(dest,src):
    if not isinstance(src,dict):return
    for key,value in src.items():
        if key not in dest:continue
        old=dest[key]
        if isinstance(old,dict):merge_config(old,value)
        elif type(old) is type(value):dest[key]=value
        elif value is None:continue
        elif isinstance(old,str) and isinstance(value,(bool,int,float)):
            dest[key]=str(value).lower() if isinstance(value,bool) else str(value)


def load_config(overrides):
    cfg=copy.deepcopy(DEFAULTS)
    home=os.path.expanduser('~')
    path=overrides.get('config-file','')
    if not path:
        candidate=os.path.join(home,'.config/gdu/gdu.yaml')
        path=candidate if os.path.isfile(candidate) else os.path.join(home,'.gdu.yaml')
    error=None
    try:
        with open(path,encoding='utf-8') as f:contents=f.read()
        merge_config(cfg,read_yaml(contents))
    except OSError as e:error=os_error(e,path=path)
    except (ValueError,TypeError):error='yaml: invalid configuration'
    cfg.update(overrides)
    cfg['config-file']=path
    cfg.setdefault('show-disks',False);cfg.setdefault('version',False);cfg.setdefault('write-config',False)
    return cfg,error


def yaml_value(v):
    if isinstance(v,bool):return 'true' if v else 'false'
    if isinstance(v,int):return str(v)
    if not v:return '""'
    if v.startswith('#'):return "'"+v.replace("'","''")+"'"
    if v in ('true','false','null','yes','no') or any(x in v for x in '\n\r\t') or ': ' in v or ' #' in v or v[0] in '[{&*!|>\'"%@`' or v[-1].isspace() or v[0].isspace():
        return json.dumps(v,ensure_ascii=False)
    return v


def dump_yaml(data,indent=0):
    output=[];pad=' '*indent
    for key,val in data.items():
        if isinstance(val,dict):output.append(f'{pad}{key}:\n'+dump_yaml(val,indent+4))
        elif isinstance(val,list):
            if not val:output.append(f'{pad}{key}: []\n')
            else:output.append(f'{pad}{key}:\n'+''.join(' '*(indent+4)+'- '+yaml_value(x)+'\n' for x in val))
        else:output.append(f'{pad}{key}: {yaml_value(val)}\n')
    return ''.join(output)


def write_config(cfg):
    path=cfg['config-file']
    try:
        fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_TRUNC,0o600)
        with os.fdopen(fd,'w',encoding='utf-8') as f:
            f.write(dump_yaml({k:cfg[k] for k in DEFAULTS}))
    except OSError as e:raise AppError(f'error writing config file {path}: {os_error(e,path=path)}')


def help_text():
    path=os.path.join(os.path.dirname(__file__),'help.txt')
    if os.path.isfile(path):
        with open(path) as f:contents=f.read()
    else:
        with zipfile.ZipFile(sys.argv[0]) as z:contents=z.read('help.txt').decode()
    cores=os.cpu_count() or 1
    return contents.replace('64 cores available (default 64)',f'{cores} cores available (default {cores})')


class Logger:
    def __init__(self,path):
        self.file=None
        try:self.file=open(path,'a',encoding='utf-8')
        except OSError as e:raise AppError('opening log file: '+os_error(e,path=path))
    def info(self,text):
        timestamp=datetime.datetime.now(datetime.timezone.utc).strftime('%Y-%m-%dT%H:%M:%SZ')
        self.file.write(f'time="{timestamp}" level=info msg={go_quote(text)}\n');self.file.flush()
    def close(self):
        if self.file:self.file.close()
PY"}

