    sys.stdout.write('      Device      Size      Used      Free Used% Mount point\n')
    for dev,path,size,used,free in list_disks():
        pct=100*used/size if size else 0
        sys.stdout.write(f'{dev:>12} {format_size(size,cfg)} {format_size(used,cfg)} {format_size(free,cfg)} {pct:4.0f}% {path}\n')


