"""Filesystem traversal, analysis data, and the machine-readable interchange format."""
import datetime
import json
import os
import re
import sqlite3
import stat
import sys
import time
from dataclasses import dataclass, field
from cli import AppError, go_quote, os_error


@dataclass(eq=False)
class Node:
    name: str
    path: str
    directory: bool = False
    size: int = 0
    usage: int = 0
    mtime: int = 0
    own_mtime: int = 0
    count: int = 1
    flag: str = ' '
    inode: int = 0
    notreg: bool = False
    hardlink: bool = False
    children: list = field(default_factory=list)
    parent: object = None
    identifier: int = 0

    def ordered(self, apparent=False, reverse=False, by='size'):
