            elif 'unterminated subpattern' in msg:bad=('missing closing )',pattern)
            elif 'unbalanced parenthesis' in msg:bad=('unexpected )',pattern[pos:pos+1])
            elif 'nothing to repeat' in msg:bad=('missing argument to repetition operator',pattern[pos:pos+1])
            elif 'multiple repeat' in msg:bad=('invalid nested repetition operator',pattern[max(0,pos-1):pos+1])
            elif 'bad character range' in msg:
