def json_error(text,exc):
    msg=exc.msg;pos=exc.pos
    if not text.strip() or pos>=len(text):return 'unexpected end of JSON input'
    char=text[pos]
    if msg=='Extra data':return f"invalid character {go_char(char)} after top-level value"
    # Go's decoder reports the first bad character in literals rather than their start.
    for literal in ['null','true','false']:
        if text[pos:pos+1]==literal[0]:
            for j,c in enumerate(literal):
                if pos+j>=len(text):return 'unexpected end of JSON input'
                if text[pos+j]!=c:return f"invalid character {go_char(text[pos+j])} in literal {literal} (expecting {go_char(c)})"
    if msg.startswith('Unterminated string'):return 'unexpected end of JSON input'
    if msg=='Expecting property name enclosed in double quotes':return f"invalid character {go_char(char)} looking for beginning of object key string"
    if msg=="Expecting ':' delimiter":return f"invalid character {go_char(char)} after object key"
    if msg=="Expecting ',' delimiter":
        context='object key:value pair' if text.rfind('{',0,pos)>text.rfind('[',0,pos) else 'array element'
