            else:continue
            node.children.append(child);node.count+=child.count
            node.size=int64(node.size+size);node.usage=int64(node.usage+usage)
            node.mtime=max(node.mtime,child.mtime)
        return node
    return read_dir(data[3],None)


def json_dump(obj):
    s=json.dumps(obj,separators=(',',':'),ensure_ascii=False)
    return s.replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026').replace('\u2028','\\u2028').replace('\u2029','\\u2029')


def export_analysis(root,timestamp=None,empty=False):
    timestamp=int(time.time()) if timestamp is None else timestamp
    header='[1,2,'+json_dump({'progname':'gdu','progver':'dev','timestamp':timestamp})+',\n'
    if empty:return header+']\n'
    def dump_directory(node,isroot=False):
        attr={'name':node.path if isroot else node.name}
        if node.own_mtime:attr['mtime']=node.own_mtime
        out='['+json_dump(attr)
        if not node.children:return out+'\n]'
        for child in node.children:
            out+=',\n'
            if child.directory:out+=dump_directory(child)
            else:
                attr={'name':child.name}
                if child.size:attr['asize']=child.size
                if child.usage:attr['dsize']=child.usage
                if child.own_mtime:attr['mtime']=child.own_mtime
                if child.inode:attr['ino']=child.inode
                if child.hardlink:attr['hlnkc']=True
                if child.notreg:attr['notreg']=True
                out+=json_dump(attr)
        return out+']'
    return header+dump_directory(root,True)+']\n'


SCHEMA = '''CREATE TABLE IF NOT EXISTS items (
        id INTEGER PRIMARY KEY,
        parent_id INTEGER REFERENCES items(id),
        name TEXT NOT NULL,
        is_dir INTEGER NOT NULL,
        size INTEGER NOT NULL,
        usage INTEGER NOT NULL,
        mtime INTEGER NOT NULL,
        item_count INTEGER NOT NULL DEFAULT 1,
        mli INTEGER NOT NULL DEFAULT 0,
        flag TEXT NOT NULL DEFAULT ' '
    );
    CREATE INDEX IF NOT EXISTS idx_items_parent_id ON items(parent_id);
    CREATE INDEX IF NOT EXISTS idx_items_mli ON items(mli) WHERE mli != 0;
    CREATE TABLE IF NOT EXISTS metadata (key TEXT PRIMARY KEY, value TEXT);'''


class Storage:
    def __init__(self,path):
        self.path=path;self.badger=path.endswith('.badger')
        try:
            if self.badger:
                os.makedirs(path,exist_ok=True);path=os.path.join(path,'analysis.sqlite')
            self.db=sqlite3.connect(path)
            self.db.executescript(SCHEMA)
        except (sqlite3.Error,OSError):
            raise AppError('creating sqlite analyzer: unable to open database file: out of memory (14)')
    def save(self,node):
        db=self.db;db.execute('DELETE FROM items');db.execute('DELETE FROM metadata')
        def save_node(n,parent):
            c=db.execute('INSERT INTO items(parent_id,name,is_dir,size,usage,mtime,item_count,mli,flag) VALUES (?,?,?,?,?,?,?,?,?)',
                (parent,n.name,int(n.directory),n.size,n.usage,n.mtime,n.count,n.inode,n.flag))
            n.identifier=c.lastrowid
            for child in n.children:save_node(child,n.identifier)
        save_node(node,None)
        db.execute('INSERT INTO metadata VALUES (?,?)',('top_dir_path',node.path));db.commit()
    def load(self):
        data=self.db.execute('SELECT id,parent_id,name,is_dir,size,usage,mtime,item_count,mli,flag FROM items ORDER BY id').fetchall()
        if not data:return None
        meta=dict(self.db.execute('SELECT key,value FROM metadata').fetchall())
        nodes={};root=None
        for ident,parent,name,isdir,size,usage,mtime,count,mli,flag in data:
            p=nodes.get(parent);path=os.path.join(p.path,name) if p else meta.get('top_dir_path',name)
            node=Node(name,path,bool(isdir),size,usage,mtime,mtime,count,flag,mli,
                      flag=='@',flag=='H',parent=p,identifier=ident)
            nodes[ident]=node
            if p:p.children.append(node)
            else:root=node
        return root
