        elif self.modal in ('delete','empty'):
            n=self.selected()
            action='delete' if self.modal=='delete' else 'empty'
            x,y,w,h=self.box(44,8,double=True)
            self.centered(y+2,x+1,w-2,'Are you sure you want to '+action)
            target=go_target(n,self.marks)
            self.centered(y+3,x+1,w-2,target+'?')
            labels=['no','yes',"don't ask me again"]
            col=x+5
            for i,label in enumerate(labels):
                self.put(y+5,col,label,self.selected_attr if self.dialog_index==i else 0);col+=len(label)+5
        elif self.modal=='export':
            x,y,w,h=self.box(50,8,'Export data to JSON',True)
            self.put(y+2,x+2,'File name '+self.modal_input,maxwidth=w-4)
            self.centered(y+4,x+1,w-2,'Export',self.selected_attr)
        elif self.modal=='message':
            lines=textwrap.wrap(self.message,52) or ['']
            x,y,w,h=self.box(max(30,min(58,max(map(len,lines))+6)),len(lines)+6,double=True)
            for i,line in enumerate(lines):self.centered(y+2+i,x+1,w-2,line)
            self.centered(y+h-2,x+1,w-2,'OK',self.selected_attr)

    def render_viewer(self,start,capacity):
        try:
            with open(self.viewer.path,'rb') as f:data=f.read(1024*1024).decode('utf-8','replace')
        except OSError:data=''
        lines=[]
        for line in data.splitlines():
            lines.extend([line[i:i+self.w] for i in range(0,len(line),self.w)] or [''])
        for y,line in enumerate(lines[self.viewer_scroll:self.viewer_scroll+capacity]):self.put(start+y,0,line)

    def render_devices(self,start):
        self.put(start,0,'      Device      Size      Used      Free Used% Mount point')
        for i,(dev,path,size,used,free) in enumerate(self.devices[:self.h-start-2]):
            pct=used/size*100 if size else 0
            self.put(start+i+1,0,f'{dev:>12} {format_size(size,self.ui_cfg)} {format_size(used,self.ui_cfg)} {format_size(free,self.ui_cfg)} {pct:4.0f}% {path}', self.selected_attr if i==self.index else 0)

    def rescan(self):
        if not self.current:return
        parent=self.current.parent
        try:new=self.scanner.scan(self.current.path)
        except AppError as e:self.message=str(e);self.modal='message';return
        new.parent=parent
        if parent:
            parent.children=[new if n is self.current else n for n in parent.children]
        else:self.root=new
        self.current=new;self.offset=0

    def go_parent(self):
        old=self.current
        if old.parent is not None:self.current=old.parent
        else:
            path=os.path.dirname(old.path)
            if path==old.path:return
            try:self.current=self.scanner.scan(path);self.root=self.current
            except AppError:return
        self.query='';self.search_visible=False;self.offset=0
        self.visible=self.ordered()
        self.index=next((i for i,n in enumerate(self.visible) if n and n.name==old.name),0)
        if self.cfg['change-cwd']:
            try:os.chdir(self.current.path)
            except OSError:pass

    def enter(self):
        n=self.selected()
        if n is None:
            if self.current.parent:self.go_parent()
        elif n.directory:
            if self.cfg['collapse-path']:
                while len(n.children)==1 and n.children[0].directory:n=n.children[0]
            self.current=n;self.index=0;self.offset=0;self.query='';self.search_visible=False
            if self.cfg['change-cwd']:
                try:os.chdir(n.path)
                except OSError:pass
        elif self.cfg['archive-browsing'] and n.name.lower().endswith(('.zip','.jar')):
            self.enter_archive(n)

    def enter_archive(self,node):
        try:
            with zipfile.ZipFile(node.path) as z:entries=z.infolist()
        except (OSError,zipfile.BadZipFile):return
        root=Node(node.name,node.path,True,parent=self.current)
        for info in entries:
            cur=root;parts=info.filename.strip('/').split('/')
            for part in parts[:-1]:
                found=next((n for n in cur.children if n.name==part and n.directory),None)
                if found is None:
                    found=Node(part,cur.path+'/'+part,True,parent=cur);cur.children.append(found)
                cur=found
            child=Node(parts[-1],cur.path+'/'+parts[-1],info.is_dir(),info.file_size,info.compress_size,parent=cur)
            cur.children.append(child)
        def total(n):
            for c in n.children:
                total(c);n.size+=c.size;n.usage+=c.usage;n.count+=c.count
        total(root);self.current=root;self.index=0;self.offset=0

    def perform_delete(self,empty=False):
        n=self.selected();targets=list(self.marks) if self.marks else [n.path] if n else []
        for path in targets:
            try:
                if os.path.isdir(path) and not os.path.islink(path):
                    if empty:
                        for child in os.scandir(path):
                            if child.is_dir(follow_symlinks=False):shutil.rmtree(child.path)
                            else:os.unlink(child.path)
                    else:shutil.rmtree(path)
                elif empty:
                    with open(path,'wb'):pass
                else:os.unlink(path)
            except OSError as e:
                self.message=str(e);self.modal='message';return
        self.marks.clear();self.rescan()

    def handle_modal(self,key):
        modal=self.modal
        if modal in ('help','info','message'):
            if key in ('q','Q','\x1b','\x03','\n','\r','?','i'):self.modal=None
        elif modal in ('delete','empty'):
            if key in ('q','n','\x1b','\x03'):self.modal=None
            elif key in ('\t',curses.KEY_RIGHT,'l'):self.dialog_index=(self.dialog_index+1)%3
            elif key in (curses.KEY_LEFT,'h'):self.dialog_index=(self.dialog_index-1)%3
            elif key in ('y','Y','\n','\r'):
                confirm=key in ('y','Y') or self.dialog_index>0
                self.modal=None
                if confirm:
                    if self.dialog_index==2:self.cancel_confirm=True
                    self.perform_delete(modal=='empty')
        elif modal=='export':
            if key in ('\x1b','\x03'):self.modal=None
            elif key in ('\n','\r'):
                try:
                    with open(self.modal_input,'w') as f:f.write(export_analysis(self.root))
                    self.modal=None
                except OSError as e:self.message=str(e);self.modal='message'
            elif key in (curses.KEY_BACKSPACE,'\x7f','\b'):self.modal_input=self.modal_input[:-1]
            elif key=='\x15':self.modal_input=''
            elif isinstance(key,str) and key.isprintable():self.modal_input+=key

    def run(self,screen):
        self.screen=screen;curses.raw();screen.keypad(True)
        try:curses.curs_set(0);curses.set_escdelay(50)
        except (curses.error,AttributeError):pass
        self.header_attr=0;self.selected_attr=curses.A_REVERSE
        try:
            curses.start_color();curses.use_default_colors()
            curses.init_pair(1,curses.COLOR_BLACK,curses.COLOR_CYAN)
            curses.init_pair(2,curses.COLOR_WHITE,curses.COLOR_WHITE if self.cfg['no-color'] else curses.COLOR_BLUE)
            self.header_attr=curses.color_pair(1);self.selected_attr=curses.color_pair(2)
        except curses.error:pass
        while True:
            self.render()
            try:key=screen.get_wch()
            except curses.error:continue
            if key==curses.KEY_RESIZE:continue
            if self.modal:self.handle_modal(key);continue
            if self.editing:
                if key in ('\n','\r','\x1b'):self.editing=False
                elif key=='\x03':break
                elif key in (curses.KEY_BACKSPACE,'\x7f','\b'):self.query=self.query[:-1];self.index=0
                elif key=='\x15':self.query='';self.index=0
                elif isinstance(key,str) and key.isprintable():self.query+=key;self.index=0
                continue
            if self.viewer:
                if key in ('q','Q','\x1b','\x03'):self.viewer=None
                elif key in (curses.KEY_DOWN,'j'):self.viewer_scroll+=1
                elif key in (curses.KEY_UP,'k'):self.viewer_scroll=max(0,self.viewer_scroll-1)
                elif key in (curses.KEY_NPAGE,' '):self.viewer_scroll+=self.h-3
                elif key in (curses.KEY_PPAGE,):self.viewer_scroll=max(0,self.viewer_scroll-self.h+3)
                elif key=='g':self.viewer_scroll=0
                continue
            if key in ('q','Q','\x03'):
                if key=='Q' and self.current:self.quit_path=self.current.path
                break
            if self.devices is not None:
                if key in (curses.KEY_DOWN,'j'):self.index=min(len(self.devices)-1,self.index+1)
                elif key in (curses.KEY_UP,'k'):self.index=max(0,self.index-1)
                elif key in ('\n','\r',curses.KEY_RIGHT,'l') and self.devices:
                    try:self.current=self.scanner.scan(self.devices[self.index][1]);self.root=self.current;self.devices=None;self.index=0
                    except AppError:pass
                continue
            if key in (curses.KEY_DOWN,'j'):self.index=min(len(self.visible)-1,self.index+1)
            elif key in (curses.KEY_UP,'k'):self.index=max(0,self.index-1)
            elif key in ('g',curses.KEY_HOME):self.index=0
            elif key in ('G',curses.KEY_END):self.index=max(0,len(self.visible)-1)
            elif key==curses.KEY_NPAGE:self.index=min(len(self.visible)-1,self.index+self.h-3)
            elif key==curses.KEY_PPAGE:self.index=max(0,self.index-self.h+3)
            elif key in (curses.KEY_RIGHT,'l','\n','\r'):self.enter()
            elif key in (curses.KEY_LEFT,'h'):self.go_parent()
            elif key in ('s','n','C','M'):
                by={'s':'size','n':'name','C':'itemCount','M':'mtime'}[key]
                self.asc=not self.asc if self.by==by else True;self.by=by;self.index=0;self.offset=0
                self.markcol=False
            elif key=='a':self.cfg['show-apparent-size']=not self.cfg['show-apparent-size']
            elif key=='B':self.cfg['show-relative-size']=not self.cfg['show-relative-size']
            elif key in ('c','m'):
                flag='show-item-count' if key=='c' else 'show-mtime';self.cfg[flag]=not self.cfg[flag]
            elif key=='?':self.modal='help'
            elif key=='i' and self.selected():self.modal='info'
            elif key in ('/','\x06'):self.search_visible=True;self.editing=True
            elif key=='=':self.query='';self.search_visible=False;self.index=0
            elif key==' ' and self.selected():
                path=self.selected().path;self.markcol=True
                if path in self.marks:self.marks.remove(path)
                else:self.marks.add(path)
                self.index=min(len(self.visible)-1,self.index+1)
            elif key=='u':self.marks.clear()
            elif key in ('d','e') and not self.cfg['no-delete'] and self.selected():
                if self.cancel_confirm:self.perform_delete(key=='e')
                else:self.modal='delete' if key=='d' else 'empty';self.dialog_index=0
            elif key=='r':self.rescan()
            elif key=='v' and self.selected():
                n=self.selected()
                if not n.directory:self.viewer=n;self.viewer_scroll=0
            elif key=='I' and self.selected():
                self.current.children.remove(self.selected());self.index=0
            elif key=='E':self.modal='export';self.modal_input='export.json'
            elif key=='b' and not self.cfg['no-spawn-shell']:
                curses.def_prog_mode();curses.endwin()
                try:subprocess.run([os.environ.get('SHELL','/bin/sh')],cwd=self.current.path)
                except OSError:pass
                curses.reset_prog_mode();screen.clear()
            elif key=='o' and self.selected():
                try:subprocess.Popen(['xdg-open',self.selected().path],stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL)
                except OSError:pass


def go_target(node,marks):
    if marks:return f'{len(marks)} items'
    return '"'+node.name+'"' if node else 'this item'


def run_tui(root,cfg,scanner):
    browser=Browser(root,cfg,scanner)
    try:curses.wrapper(browser.run)
    except curses.error as e:raise AppError(str(e))
    if browser.quit_path:print(browser.quit_path)


def run_devices(cfg,scanner,devices):
    browser=Browser(None,cfg,scanner,devices)
    try:curses.wrapper(browser.run)
    except curses.error as e:raise AppError(str(e))
